27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164, e.g. +61412345678")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    public Integer getNamesakeCount() {
67	        return this.namesakeCount;
68	    }
69	
70	    public void setNamesakeCount(Integer namesakeCount) {
71	        this.namesakeCount = namesakeCount;
72	    }
73	
74	    public String getCustomerCode() {
75	        return this.customerCode;
76	    }
77	
78	    public void setCustomerCode(String customerCode) {
79	        this.customerCode = customerCode;
80	    }
81	
82	    public String getHouseholdId() {
83	        return this.householdId;
84	    }
85	
86	    public void setHouseholdId(String householdId) {
87	        this.householdId = householdId;
88	    }
89	
90	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
91	    private Set<Pet> pets;
92	
93	    public LocalDate getRegistrationDate() {
94	        return this.registrationDate;
95	    }
96	
97	    public void setRegistrationDate(LocalDate registrationDate) {
98	        this.registrationDate = registrationDate;
99	    }
100	
101	    /** Default the registration date to the server's current date when none was supplied. */
102	    @PrePersist
103	    void defaultRegistrationDate() {
104	        if (this.registrationDate == null) {
105	            this.registrationDate = LocalDate.now();
106	        }
107	    }
108	
109	    public String getEmail() {
110	        return this.email;
111	    }
112	
113	    public void setEmail(String email) {
114	        this.email = email;
115	    }
116	
117	    public String getAddress() {
118	        return this.address;
119	    }
120	
121	    public void setAddress(String address) {
122	        this.address = address;
123	    }
124	
125	    public String getCity() {
126	        return this.city;
127	    }
128	
129	    public void setCity(String city) {
130	        this.city = city;
131	    }
132	
133	    public String getTelephone() {
134	        return this.telephone;
135	    }
136	
137	    public void setTelephone(String telephone) {
138	        this.telephone = telephone;
139	    }
140	
141	    protected Set<Pet> getPetsInternal() {
142	        if (this.pets == null) {
143	            this.pets = new HashSet<>();
144	        }
145	        return this.pets;
146	    }
147	
148	    protected void setPetsInternal(Set<Pet> pets) {
149	        this.pets = pets;
150	    }
151	
152	    public List<Pet> getPets() {
153	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
154	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
155	        return Collections.unmodifiableList(sortedPets);
156	    }
157	
158	    public void setPets(List<Pet> pets) {
159	        this.pets = new HashSet<>(pets);
160	    }
161	
162	    public void addPet(Pet pet) {
163	        getPetsInternal().add(pet);
164	        pet.setOwner(this);
165	    }
166	
167	    /**
168	     * Return the Pet with the given name, or null if none found for this Owner.
169	     *
170	     * @param name to test
171	     * @return true if pet name is already in use
172	     */
173	    public Pet getPet(String name) {
174	        return getPet(name, false);
175	    }
176	
177	    /**
178	     * Return the Pet with the given name, or null if none found for this Owner.
179	     *
180	     * @param name to test
181	     * @return true if pet name is already in use
182	     */
183	    public Pet getPet(String name, boolean ignoreNew) {
184	        name = name.toLowerCase();
185	        for (Pet pet : getPetsInternal()) {
186	            if (!ignoreNew || !pet.isNew()) {
187	                String compName = pet.getName();
188	                compName = compName.toLowerCase();
189	                if (compName.equals(name)) {
190	                    return pet;
191	                }
192	            }
193	        }
194	        return null;
195	    }
196	
197	    public Pet getPet(Integer petId) {
198	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
199	    }
200	
201	    @Override
202	    public String toString() {
203	        return new ToStringCreator(this)
204	
205	            .append("id", this.getId())
206	            .append("new", this.isNew())
207	            .append("lastName", this.getLastName())
208	            .append("firstName", this.getFirstName())
209	            .append("address", this.address)
210	            .append("city", this.city)
211	            .append("telephone", this.telephone)
212	            .toString();
213	    }
214	}
