27	        }
28	        else {
29	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
30	            digits = "61" + national;
31	        }
32	        if (!digits.matches("[0-9]{8,15}")) {
33	            return cleaned;
34	        }
35	        return "+" + digits;
36	    }
