37	            if (!existing.getId().equals(owner.getId())
38	                && lastName.equals(normalize(existing.getLastName()))
39	                && address.equals(normalize(existing.getAddress()))) {
40	                if (!Boolean.TRUE.equals(sharesHousehold)) {
41	                    throw new DuplicateHouseholdException();
42	                }
43	                owner.setHouseholdId(householdId(lastName, address));
44	                return;
45	            }
46	        }
47	    }
48	
49	    private static String normalize(String value) {
50	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
51	    }
52	
53	    /** Derive a stable identifier shared by every owner in the same (last name, address) household. */
54	    private static String householdId(String lastName, String address) {
55	        try {
56	            byte[] digest = MessageDigest.getInstance("SHA-256")
57	                .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
58	            StringBuilder sb = new StringBuilder();
59	            for (int i = 0; i < 8; i++) {
60	                sb.append(String.format("%02x", digest[i]));
61	            }
62	            return sb.toString();
63	        }
64	        catch (NoSuchAlgorithmException e) {
65	            throw new IllegalStateException(e);
66	        }
67	    }
68	
69	    /** Thrown when another owner already shares the same last name and address. */
70	    @ResponseStatus(HttpStatus.CONFLICT)
71	    public static class DuplicateHouseholdException extends RuntimeException {
72	    }
73	}
