7	/**
8	 * Business rule: an owner's telephone must be unique across all owners once normalized
9	 * (non-digit characters removed). Kept as a small, self-contained unit so the rule can be
10	 * enforced from the create flow without adding complexity to the controller or service.
11	 *
12	 * @author Vitaliy Fedoriv
13	 */
14	public final class OwnerTelephonePolicy {
15	
16	    private OwnerTelephonePolicy() {
17	    }
18	
19	    /**
20	     * Reject the given owner if its normalized telephone matches any other existing owner.
21	     *
22	     * @param clinicService source of the existing owners
23	     * @param owner         the owner being created
24	     * @throws DuplicateTelephoneException if the normalized telephone is already in use
25	     */
26	    public static void rejectDuplicateTelephone(ClinicService clinicService, Owner owner) {
27	        String normalized = normalize(owner.getTelephone());
28	        if (normalized.isEmpty()) {
29	            return;
30	        }
31	        for (Owner existing : clinicService.findAllOwners()) {
32	            if (!existing.getId().equals(owner.getId()) && normalized.equals(normalize(existing.getTelephone()))) {
33	                throw new DuplicateTelephoneException();
34	            }
35	        }
36	    }
37	
38	    private static String normalize(String telephone) {
39	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
40	    }
41	
42	    /** Thrown when an owner's normalized telephone is already used by another owner. */
43	    @ResponseStatus(HttpStatus.CONFLICT)
44	    public static class DuplicateTelephoneException extends RuntimeException {
45	    }
46	}
