44	/**
45	 * Global Exception handler for REST controllers.
46	 * <p>
47	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
48	 *
49	 * @author Vitaliy Fedoriv
50	 * @author Alexander Dudkin
51	 */
52	@ControllerAdvice
53	public class ExceptionControllerAdvice {
54	
55	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
56	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
57	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
58	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
59	
60	    /**
61	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
62	     * class.
63	     *
64	     * @param e     Object referring to the thrown exception.
65	     * @param status HTTP response status.
66	     * @param url URL request.
67	     */
68	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
69	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
70	        problemDetail.setType(URI.create(url.toString()));
71	        problemDetail.setTitle(e.getClass().getSimpleName());
72	        problemDetail.setDetail(detail);
73	        problemDetail.setProperty("timestamp", Instant.now());
74	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
75	        return problemDetail;
76	    }
77	
78	    /**
79	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
80	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
81	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
82	     * would catch it and report an authorization failure as a 500.
83	     *
84	     * @param e The {@link AccessDeniedException} to propagate
85	     * @throws AccessDeniedException always
86	     */
87	    @ExceptionHandler(AccessDeniedException.class)
88	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
89	        throw e;
90	    }
91	
92	    /**
93	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
94	     *
95	     * @param e The {@link Exception} to be handled
96	     * @param request {@link HttpServletRequest} object referring to the current request.
97	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
98	     */
99	    @ExceptionHandler(Exception.class)
100	    @ResponseBody
101	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
102	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
103	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
104	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
105	        return ResponseEntity.status(status).body(detail);
106	    }
107	
108	    /**
109	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
110	     * method returns a 404 Not Found status if an entity does not exist.
111	     *
112	     * @param e The {@link DataIntegrityViolationException} to be handled
113	     * @param request {@link HttpServletRequest} object referring to the current request.
114	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
115	     */
116	    @ExceptionHandler(DataIntegrityViolationException.class)
117	    @ResponseBody
118	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
119	        logger.warn("Data integrity violation at {} {}: {}",
120	            request.getMethod(),
121	            request.getRequestURI(),
122	            e.getMessage());
123	        logger.debug("Data integrity violation stacktrace", e);
124	        HttpStatus status = HttpStatus.NOT_FOUND;
125	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
126	        return ResponseEntity.status(status).body(detail);
127	    }
128	
129	    /**
130	     * Handles exception thrown by Bean Validation on controller methods parameters
131	     *
132	     * @param e The {@link MethodArgumentNotValidException} to be handled
133	     * @param request {@link HttpServletRequest} object referring to the current request.
134	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
135	     */
136	    /**
137	     * Handles {@link OwnerTelephonePolicy.DuplicateTelephoneException} by returning a 409 Conflict,
138	     * signalling that the submitted telephone is already used by another owner.
139	     *
140	     * @param e The {@link OwnerTelephonePolicy.DuplicateTelephoneException} to be handled
141	     * @param request {@link HttpServletRequest} object referring to the current request.
142	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
143	     */
144	    @ExceptionHandler(OwnerTelephonePolicy.DuplicateTelephoneException.class)
145	    @ResponseBody
146	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(OwnerTelephonePolicy.DuplicateTelephoneException e, HttpServletRequest request) {
147	        HttpStatus status = HttpStatus.CONFLICT;
148	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), "The telephone number is already used by another owner");
149	        return ResponseEntity.status(status).body(detail);
150	    }
151	
152	    @ExceptionHandler(OwnerCityCapacityPolicy.CityAtCapacityException.class)
153	    @ResponseBody
154	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(OwnerCityCapacityPolicy.CityAtCapacityException e, HttpServletRequest request) {
155	        HttpStatus status = HttpStatus.CONFLICT;
156	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), "The owner's city already contains the maximum number of owners");
157	        return ResponseEntity.status(status).body(detail);
158	    }
159	
160	    @ExceptionHandler(OwnerDailyLimitPolicy.DailyLimitReachedException.class)
161	    @ResponseBody
162	    public ResponseEntity<ProblemDetail> handleDailyLimitReachedException(OwnerDailyLimitPolicy.DailyLimitReachedException e, HttpServletRequest request) {
163	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
164	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), "The maximum number of owners for today has already been reached");
165	        return ResponseEntity.status(status).body(detail);
166	    }
167	
168	    @ExceptionHandler(OwnerHouseholdPolicy.DuplicateHouseholdException.class)
169	    @ResponseBody
170	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(OwnerHouseholdPolicy.DuplicateHouseholdException e, HttpServletRequest request) {
171	        HttpStatus status = HttpStatus.CONFLICT;
172	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), "Another owner already shares this last name and address");
173	        return ResponseEntity.status(status).body(detail);
174	    }
175	
176	    @ExceptionHandler(MethodArgumentNotValidException.class)
177	    @ResponseBody
178	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
179	        HttpStatus status = HttpStatus.BAD_REQUEST;
180	        BindingErrorsResponse errors = new BindingErrorsResponse();
181	        BindingResult bindingResult = e.getBindingResult();
182	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
183	        if (bindingResult.hasErrors()) {
184	            errors.addAllErrors(bindingResult);
185	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
186	                .map(fieldError -> {
187	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
188	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
189	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
190	                        fieldError.getField(),
191	                        defaultMessage,
192	                        rejectedValue);
193	                    return new ValidationMessageDto(message)
194	                        .putAdditionalProperty("field", fieldError.getField())
195	                        .putAdditionalProperty("rejectedValue", rejectedValue)
196	                        .putAdditionalProperty("defaultMessage", defaultMessage);
197	                })
198	                .toList();
199	            logger.debug("Validation error at {} {}: {}",
200	                request.getMethod(),
201	                request.getRequestURI(),
202	                bindingResult.getFieldErrors());
203	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
204	            detail.setProperty("errors", bindingResult.getFieldErrors().stream()
205	                .map(fieldError -> fieldError.getField())
206	                .distinct()
207	                .toList());
208	            return ResponseEntity.status(status).body(detail);
209	        }
210	        return ResponseEntity.status(status).body(detail);
211	    }
212	
213	}
