3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Business rule: an owner's {@code membershipNumber} is derived as
9	 * {@code <customerCode>-M<YY>}, where YY is the last two digits of the registration-date
10	 * year (e.g. {@code SMI-0007-M26}). Kept as a small, self-contained unit so the rule can be
11	 * applied from the read flow without adding complexity to the mapper, controller, or service.
12	 */
13	public final class OwnerMembershipPolicy {
14	
15	    private OwnerMembershipPolicy() {
16	    }
17	
18	    /**
19	     * Derive the {@code membershipNumber} for the given owner, or {@code null} when the
20	     * customer code or registration date it is built from is not yet available.
21	     *
22	     * @param owner the owner whose membership number to derive
23	     * @return the membership number, or {@code null} if it cannot be derived
24	     */
25	    public static String membershipNumber(Owner owner) {
26	        String customerCode = owner.getCustomerCode();
27	        LocalDate registrationDate = owner.getRegistrationDate();
28	        if (customerCode == null || registrationDate == null) {
29	            return null;
30	        }
31	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
32	    }
33	}
