7	/**
8	 * Business rule: an owner's {@code locality} is the canonical region derived from its city using a
9	 * fixed city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), or {@code UNKNOWN} when
10	 * the city is not in the table. Kept as a small, self-contained unit so the rule can be applied from
11	 * the read flow without adding complexity to the mapper, controller, or service.
12	 */
13	public final class OwnerLocalityPolicy {
14	
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
17	
18	    private OwnerLocalityPolicy() {
19	    }
20	
21	    /**
22	     * Derive the {@code locality} for the given owner.
23	     *
24	     * @param owner the owner whose locality to derive
25	     * @return the canonical region for the owner's city, or {@code "UNKNOWN"} when the city is
26	     *     not in the fixed city-to-region table
27	     */
28	    public static String locality(Owner owner) {
29	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
